args.command:
$jobId = "1ef7cf24da55"
$start = Get-Date
Write-Output "START $($start.ToString('o'))"
$deadline = (Get-Date).AddSeconds(400)
do {
  try {
    $r = Invoke-RestMethod -Uri "http://localhost:8000/api/v1/jobs/$jobId" -Method Get
    $now = Get-Date
    $elapsed = [int]($now - $start).TotalSeconds
    Write-Output "[$elapsed s] status=$($r.status) stage=$($r.stage) progress=$($r.progress)"
    $r | ConvertTo-Json -Depth 10 -Compress | Write-Output
    if ($r.status -eq "ready" -or $r.status -eq "failed") { break }
  } catch { Write-Output "poll error: $_" }
  Start-Sleep -Seconds 10
} while ((Get-Date) -lt $deadline)
$end = Get-Date
Write-Output "FINISH $($end.ToString('o')) TOTAL $([int]($end-$start).TotalSeconds)s"

